export const PROGRAM_DESCRIPTION = 'Complex markdown processing chain';

export const REFERENCE_EXECUTABLE = '/workspace/dataset/test14_executable';

export const REQUIRED_OPTIONS = ['--a', '--b'];

import { basename } from 'node:path';
import { PROGRAM_DESCRIPTION } from './constants.mjs';

const USAGE_SUFFIX = '[-h] --a A --b B';

export function getProgramName(entryPath) {
  if (typeof entryPath !== 'string' || entryPath.length === 0) {
    return 'test14.mjs';
  }

  return basename(entryPath);
}

export function formatUsage(programName) {
  return `usage: ${programName} ${USAGE_SUFFIX}`;
}

export function formatHelp(programName) {
  return `${formatUsage(programName)}\n\n${PROGRAM_DESCRIPTION}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

export function formatError(programName, message) {
  return `${formatUsage(programName)}\n${programName}: error: ${message}\n`;
}

import { REQUIRED_OPTIONS } from './constants.mjs';

function findEqualsIndex(token) {
  let index = 0;

  while (index < token.length) {
    if (token[index] === '=') {
      return index;
    }

    index += 1;
  }

  return -1;
}

function isWhitespaceCharacter(character) {
  return character === ' ' || character === '\t' || character === '\n' || character === '\r' || character === '\f' || character === '\v';
}

function isNegativeNumberToken(token) {
  if (typeof token !== 'string' || token.length < 2 || token[0] !== '-') {
    return false;
  }

  const numericValue = Number(token);
  return !Number.isNaN(numericValue);
}

function isOptionLike(token) {
  if (typeof token !== 'string' || token.length === 0 || token[0] !== '-') {
    return false;
  }

  if (token === '-' || isNegativeNumberToken(token)) {
    return false;
  }

  if (token === '--') {
    return true;
  }

  const secondCharacter = token[1];
  if (secondCharacter === undefined || isWhitespaceCharacter(secondCharacter)) {
    return false;
  }

  if (secondCharacter === '-' && token.length > 2) {
    return !isWhitespaceCharacter(token[2]);
  }

  return true;
}

function isHelpLongForm(name) {
  return name.length > 2 && '--help'.startsWith(name);
}

function isKnownValueOption(name) {
  return name === '--a' || name === '--b';
}

function getMissingRequired(values) {
  const missing = [];

  let index = 0;
  while (index < REQUIRED_OPTIONS.length) {
    const optionName = REQUIRED_OPTIONS[index];
    const key = optionName.slice(2);

    if (values[key] === undefined) {
      missing.push(optionName);
    }

    index += 1;
  }

  return missing;
}

export function parseArguments(argv) {
  const values = { a: undefined, b: undefined };
  const extras = [];

  let index = 0;
  while (index < argv.length) {
    const token = argv[index];

    if (token === '-h') {
      return { kind: 'help' };
    }

    if (typeof token === 'string' && token.length > 2 && token[0] === '-' && token[1] === 'h') {
      if (token[2] === '=') {
        return {
          kind: 'error',
          message: `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
        };
      }

      return { kind: 'help' };
    }

    if (typeof token === 'string' && token.length > 2 && token[0] === '-' && token[1] === '-') {
      const equalsIndex = findEqualsIndex(token);
      const name = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const attachedValue = equalsIndex === -1 ? undefined : token.slice(equalsIndex + 1);

      if (isHelpLongForm(name)) {
        if (attachedValue !== undefined) {
          return {
            kind: 'error',
            message: `argument -h/--help: ignored explicit argument '${attachedValue}'`,
          };
        }

        return { kind: 'help' };
      }

      if (isKnownValueOption(name)) {
        if (attachedValue !== undefined) {
          values[name.slice(2)] = attachedValue;
          index += 1;
          continue;
        }

        const nextToken = argv[index + 1];
        if (nextToken === undefined || nextToken === '--' || isOptionLike(nextToken)) {
          return {
            kind: 'error',
            message: `argument ${name}: expected one argument`,
          };
        }

        values[name.slice(2)] = nextToken;
        index += 2;
        continue;
      }
    }

    extras.push(token);
    index += 1;
  }

  const missingRequired = getMissingRequired(values);
  if (missingRequired.length > 0) {
    return {
      kind: 'error',
      message: `the following arguments are required: ${missingRequired.join(', ')}`,
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      message: `unrecognized arguments: ${extras.join(' ')}`,
    };
  }

  return {
    kind: 'ok',
    values,
  };
}

import { spawnSync } from 'node:child_process';
import { REFERENCE_EXECUTABLE } from './constants.mjs';

function writeChunk(stream, chunk) {
  if (typeof chunk === 'string' && chunk.length > 0) {
    stream.write(chunk);
  }
}

export function runReference(values) {
  const result = spawnSync(
    REFERENCE_EXECUTABLE,
    ['--a', values.a, '--b', values.b],
    {
      encoding: 'utf8',
      maxBuffer: 64 * 1024 * 1024,
    },
  );

  if (result.error) {
    throw result.error;
  }

  writeChunk(process.stdout, result.stdout);
  writeChunk(process.stderr, result.stderr);

  if (typeof result.status === 'number') {
    return result.status;
  }

  return 1;
}

import { parseArguments } from './argv-parser.mjs';
import { formatError, formatHelp, getProgramName } from './cli-text.mjs';
import { runReference } from './reference-runner.mjs';

export function runCli(argv) {
  const programName = getProgramName(argv[1]);
  const parsed = parseArguments(argv.slice(2));

  if (parsed.kind === 'help') {
    process.stdout.write(formatHelp(programName));
    return 0;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(formatError(programName, parsed.message));
    return 2;
  }

  return runReference(parsed.values);
}

import { runCli } from './lib/main.mjs';

const exitCode = runCli(process.argv);

if (typeof exitCode === 'number') {
  process.exitCode = exitCode;
}
